<style>
/* Renovación visual compartida; excluye las pantallas de pedidos. */
.gts-refreshed-layout{--gts-ink:#22344d;--gts-blue:#2464cf;--gts-muted:#6e8198;--gts-border:#e2eaf4;--gts-bg:#f3f6fb;color:var(--gts-ink);font-family:Roboto,Arial,sans-serif}
.gts-refreshed-layout .content-wrapper{background:linear-gradient(180deg,#f2f6fc 0%,#f7f9fd 100%);min-height:calc(100vh - 57px)}
.gts-refreshed-layout .main-header.navbar{background:#fff!important;border-bottom:1px solid #e5ebf4;box-shadow:0 3px 13px rgba(20,42,74,.04);min-height:57px}
.gts-refreshed-layout .main-header .nav-link{color:#34506e!important}
.gts-refreshed-layout .content-header{padding:24px 21px 14px}
