.gts-refreshed-layout .content-wrapper .card:not(.ref-create-card){border:1px solid #e3ebf5;border-radius:14px;box-shadow:0 7px 22px rgba(18,39,69,.055);overflow:hidden}
.gts-refreshed-layout .content-wrapper .card-header{background:linear-gradient(180deg,#fff,#fbfdff);border-bottom:1px solid #eaf0f7;padding:15px 19px}
