.gts-refreshed-layout .content-wrapper .btn{border-radius:9px;font-weight:650;transition:background-color .16s,border-color .16s,box-shadow .16s}
.gts-refreshed-layout .content-wrapper .btn-primary{background:#2563d5;border-color:#2563d5}
.gts-refreshed-layout .content-wrapper .btn-primary:hover{background:#164db5;border-color:#164db5}
